using System;
using System.Text;

namespace InformationWeb.Controls.Employee_V2
{
    public static class TaskAttachmentUrl
    {
        public static string Build(string baseUrl, string relativeLink)
        {
            if (string.IsNullOrEmpty(relativeLink))
                return baseUrl ?? string.Empty;

            string basePart = baseUrl ?? string.Empty;
            if (basePart.Length > 0 && !basePart.EndsWith("/", StringComparison.Ordinal))
                basePart += "/";

            string[] parts = relativeLink.Split(new char[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
            if (parts.Length == 0)
                return basePart;

            StringBuilder sb = new StringBuilder(basePart);
            for (int i = 0; i < parts.Length; i++)
            {
                if (i > 0)
                    sb.Append("/");
                sb.Append(Uri.EscapeDataString(parts[i]));
            }
            return sb.ToString();
        }
    }
}

using System;
using System.IO;

namespace InformationWeb.Controls.Employee_V2
{
    public static class TaskAttachmentFileLifecycle
    {
        public static void FinalizeSave(string physicalRoot, long employeeId, string oldRelativeLink, string newRelativeLink)
        {
            if (string.IsNullOrEmpty(oldRelativeLink))
                return;
            if (string.Equals(oldRelativeLink, newRelativeLink, StringComparison.OrdinalIgnoreCase))
                return;
            if (!BelongsToEmployee(oldRelativeLink, employeeId))
                return;

            string path = CombinePhysicalPath(physicalRoot, oldRelativeLink);
            if (File.Exists(path))
                File.Delete(path);
        }

        public static void DiscardPending(string physicalRoot, long employeeId, string pendingRelativeLink)
        {
            if (string.IsNullOrEmpty(pendingRelativeLink))
                return;
            if (!BelongsToEmployee(pendingRelativeLink, employeeId))
                return;

            string path = CombinePhysicalPath(physicalRoot, pendingRelativeLink);
            if (File.Exists(path))
                File.Delete(path);
        }

        private static bool BelongsToEmployee(string relativeLink, long employeeId)
        {
            string prefix = employeeId.ToString() + "/";
            return relativeLink.StartsWith(prefix, StringComparison.OrdinalIgnoreCase);
        }

        private static string CombinePhysicalPath(string physicalRoot, string relativeLink)
        {
            string root = physicalRoot ?? string.Empty;
            if (root.Length > 0 && !root.EndsWith("\\") && !root.EndsWith("/"))
                root += "\\";

            string rel = relativeLink.Replace('/', Path.DirectorySeparatorChar);
            return Path.Combine(root, rel);
        }
    }
}

