protected void fileUpload_UploadedComplete(object sender, AsyncFileUploadEventArgs e)
{
    Session[GetFileUploadSessionKey()] = null;

    long employeeId = GetEmployeeId();
    if (employeeId <= 0 || !fileUpload.HasFile)
        return;

    string originalName = fileUpload.FileName.Replace(" ", "-");
    if (originalName.Length < 4)
        return;

    string ext = Path.GetExtension(originalName);
    if (ext.Length >= 4)
    {
        string ext3 = ext.Substring(ext.Length - 3).ToLower();
        if (ext3 == "exe" || ext3 == "dll" || ext3 == "bat" || ext3 == "cgi" || ext3 == "com" || ext3 == "msi")
            return;
    }

    string folder = GetEmployeeUploadFolder(employeeId);
    Directory.CreateDirectory(folder);

    string prefix = BuildUploadFilePrefix();
    string savedName = prefix + originalName;
    fileUpload.SaveAs(Path.Combine(folder, savedName));

    Session[GetFileUploadSessionKey()] = BuildRelativeLink(employeeId, savedName);
}

protected void lbtPostFile_Click(object sender, EventArgs e)
