    if (udpFile != null)
        udpFile.Update();
}

protected void lbtlDeleteFile_Click(object sender, EventArgs e)
{
    long employeeId = GetEmployeeId();
    string relativeLink = GetPendingLink();
    if (employeeId > 0 && !string.IsNullOrEmpty(relativeLink))
    {
        string path = TaskAttachmentFileLifecycle.CombinePhysicalPathForTest(GetUploadPhysicalRoot(), relativeLink);
        DeletePhysicalFileIfExists(path);
    }

    txtLinkFile.Text = string.Empty;
    Session[GetFileUploadSessionKey()] = null;
    RefreshAttachmentUi();
    ScheduleOpenModalAfterUpdate();
    if (udpFile != null)
        udpFile.Update();
    udpAll.Update();
}

