private static string BuildAttachmentViewUrl(string relativeLink)
{
    if (string.IsNullOrEmpty(relativeLink))
        return string.Empty;

    string baseUrl = GetUploadLogicalRoot();
    if (baseUrl.Length > 0 && !baseUrl.EndsWith("/"))
        baseUrl += "/";

    string[] parts = relativeLink.Split(new char[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
    if (parts.Length == 0)
        return baseUrl;

    StringBuilder sb = new StringBuilder(baseUrl);
    for (int i = 0; i < parts.Length; i++)
    {
        if (i > 0)
            sb.Append("/");
        sb.Append(Uri.EscapeDataString(parts[i]));
    }
    return sb.ToString();
}

