            if (lbtlDeleteFile != null)
                lbtlDeleteFile.Visible = canEdit && hasFile;

            if (lnkViewAttachment != null)
            {
                if (hasFile && employeeId > 0)
                {
                    lnkViewAttachment.Visible = true;
                    lnkViewAttachment.NavigateUrl = BuildAttachmentViewUrl(employeeId, link);
                }
                else
                {
                    lnkViewAttachment.Visible = false;
                    lnkViewAttachment.NavigateUrl = string.Empty;
