        private void FinalizeAttachmentAfterSave(long employeeId, string oldFileName, string newFileName)
        {
            if (string.IsNullOrEmpty(oldFileName))
                return;
            if (string.Equals(oldFileName, newFileName, StringComparison.OrdinalIgnoreCase))
                return;

            DeletePhysicalFileIfExists(GetAttachmentPhysicalPath(employeeId, oldFileName));
        }

        private void DiscardPendingAttachment(long employeeId, string pendingFileName)
        {
            if (string.IsNullOrEmpty(pendingFileName))
                return;

            DeletePhysicalFileIfExists(GetAttachmentPhysicalPath(employeeId, pendingFileName));
        }

        private static string NormalizeAttachmentFileName(string link, long employeeId)
        {
            if (string.IsNullOrWhiteSpace(link))
                return string.Empty;

            string value = link.Trim().Replace('\\', '/');
            if (employeeId <= 0)
                return value;

            string prefix = employeeId.ToString() + "/";
            if (value.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                return value.Substring(prefix.Length);

            return value;
        }

        private static string GetAttachmentPhysicalPath(long employeeId, string fileName)
        {
            if (employeeId <= 0 || string.IsNullOrWhiteSpace(fileName))
                return string.Empty;

            return Path.Combine(GetEmployeeUploadFolder(employeeId), NormalizeAttachmentFileName(fileName, employeeId));
        }

        private static string BuildAttachmentViewUrl(long employeeId, string fileName)
        {
            if (employeeId <= 0 || string.IsNullOrEmpty(fileName))
                return string.Empty;

            string baseUrl = GetUploadLogicalRoot();
            if (baseUrl.Length > 0 && !baseUrl.EndsWith("/"))
                baseUrl += "/";

            string encodedName = Uri.EscapeDataString(NormalizeAttachmentFileName(fileName, employeeId));
            return baseUrl + employeeId.ToString() + "/" + encodedName;
        }

        private static void DeletePhysicalFileIfExists(string path)
        {
            if (string.IsNullOrEmpty(path))
                return;
            if (File.Exists(path))
                File.Delete(path);
        }
